function parseMinutes(raw) {
  if (raw.trim() === "") return null;
  const n = Number(raw);
  return Number.isInteger(n) && n >= 0 ? n : null;
}
console.log(parseMinutes("0"), parseMinutes(""), parseMinutes("2.5"));
// 0 null null

