function completion(done, total) {
  return total === 0 ? 0 : Math.round(100 * done / total);
}
console.log(completion(3, 4)); // 75

exercise.solution:
function toggleById(rows, id) {
  return rows.map(row => row.id === id ? {...row, done: !row.done} : row);
}
const before = [{id:1, done:false}];
const after = toggleById(before, 1);
console.log(before[0].done, after[0].done); // false true

